"""Daily PSP settlement reconciliation engine.

Compares the internal ledger with the card processor's settlement data and
returns a list of breaks. Standard library only (Python 3.10+).
"""

from __future__ import annotations

import re
from collections import defaultdict
from datetime import date, datetime, time, timedelta, timezone
from zoneinfo import ZoneInfo

__all__ = ["reconcile"]

_NY = ZoneInfo("America/New_York")
_CUTOFF = time(17, 0)

# ISO 4217 minor-unit exponents. Anything not listed defaults to 2.
_ZERO_DECIMAL = {
    "BIF", "CLP", "DJF", "GNF", "ISK", "JPY", "KMF", "KRW", "PYG", "RWF",
    "UGX", "UYI", "VND", "VUV", "XAF", "XOF", "XPF",
}
_THREE_DECIMAL = {"BHD", "IQD", "JOD", "KWD", "LYD", "OMR", "TND"}
_FOUR_DECIMAL = {"CLF", "UYW"}

_IGNORED_TYPES = {"FEE"}

_AMOUNT_RE = re.compile(
    r"""^
    (?P<open>\()?
    \s*
    (?P<sign>-)?
    (?P<int>\d{1,3}(?:,\d{3})+|\d+)
    (?:\.(?P<frac>\d+))?
    \s*
    (?P<close>\))?
    $""",
    re.VERBOSE,
)


def _exponent(currency: str) -> int:
    c = currency.strip().upper()
    if c in _ZERO_DECIMAL:
        return 0
    if c in _THREE_DECIMAL:
        return 3
    if c in _FOUR_DECIMAL:
        return 4
    return 2


def _parse_amount(text: str, currency: str) -> int:
    """Convert a processor amount string to integer minor units, exactly."""
    if not isinstance(text, str):
        raise ValueError(f"amount must be a string, got {text!r}")
    m = _AMOUNT_RE.match(text.strip())
    if not m:
        raise ValueError(f"unparseable amount: {text!r}")
    opened, closed = m.group("open"), m.group("close")
    if bool(opened) != bool(closed):
        raise ValueError(f"unbalanced parentheses in amount: {text!r}")
    if opened and m.group("sign"):
        raise ValueError(f"ambiguous negative amount: {text!r}")

    exp = _exponent(currency)
    int_part = m.group("int").replace(",", "")
    frac = m.group("frac") or ""
    if len(frac) > exp:
        extra = frac[exp:]
        if extra.strip("0"):
            raise ValueError(
                f"amount {text!r} has more precision than {currency} allows"
            )
        frac = frac[:exp]
    frac = frac.ljust(exp, "0")

    minor = int(int_part + frac) if (int_part + frac) else 0
    if opened or m.group("sign"):
        minor = -minor
    return minor


def _parse_event_time(text: str) -> datetime:
    s = text.strip()
    if s.endswith(("Z", "z")):
        s = s[:-1] + "+00:00"
    dt = datetime.fromisoformat(s)
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt


def _business_date(event_time: str, holidays: set[str]) -> str:
    local = _parse_event_time(event_time).astimezone(_NY)
    d: date = local.date()
    if local.time() >= _CUTOFF:
        d += timedelta(days=1)
    while d.weekday() >= 5 or d.isoformat() in holidays:
        d += timedelta(days=1)
    return d.isoformat()


def _latest_batches(lines: list[dict]) -> list[dict]:
    """Keep only lines carrying the highest file_seq of their batch_id."""
    best: dict[str, int] = {}
    seqs: list[int] = []
    for ln in lines:
        seq = int(str(ln["file_seq"]).strip())
        seqs.append(seq)
        b = ln["batch_id"]
        if b not in best or seq > best[b]:
            best[b] = seq
    return [ln for ln, seq in zip(lines, seqs) if seq == best[ln["batch_id"]]]


def reconcile(
    ledger_rows: list[dict],
    settlement_lines: list[dict],
    holidays: list[str],
) -> list[dict]:
    holiday_set = {h.strip() for h in (holidays or [])}

    # ---- Ledger side -----------------------------------------------------
    ledger: dict[tuple[str, str, str], list] = {}
    for row in ledger_rows:
        if row["type"] in _IGNORED_TYPES:
            continue
        key = (row["psp_ref"], row["type"], row["currency"])
        g = ledger.setdefault(key, [0, ""])
        g[0] += int(row["amount_minor"])
        if row["business_date"] > g[1]:
            g[1] = row["business_date"]

    # ---- Settlement side -------------------------------------------------
    settlement: dict[tuple[str, str, str], list] = {}
    for ln in _latest_batches(settlement_lines):
        if ln["line_type"] in _IGNORED_TYPES:
            continue
        key = (ln["psp_ref"], ln["line_type"], ln["currency"])
        amount = _parse_amount(ln["amount"], ln["currency"])
        bdate = _business_date(ln["event_time"], holiday_set)
        g = settlement.setdefault(key, [0, ""])
        g[0] += amount
        if bdate > g[1]:
            g[1] = bdate

    # ---- Chargeback netting ---------------------------------------------
    pairs = {(k[0], k[2]) for k in settlement}
    for ref, cur in pairs:
        cb = (ref, "CHARGEBACK", cur)
        rev = (ref, "CHARGEBACK_REVERSAL", cur)
        if (
            cb in settlement
            and rev in settlement
            and settlement[cb][0] + settlement[rev][0] == 0
            and cb not in ledger
            and rev not in ledger
        ):
            del settlement[cb]
            del settlement[rev]

    # ---- Matching --------------------------------------------------------
    breaks: list[dict] = []
    for key in set(ledger) | set(settlement):
        s = settlement.get(key)
        l = ledger.get(key)
        if s is not None and l is None:
            kind, delta = "MISSING_IN_LEDGER", s[0]
        elif l is not None and s is None:
            kind, delta = "MISSING_IN_SETTLEMENT", -l[0]
        elif s[0] != l[0]:
            kind, delta = "AMOUNT_MISMATCH", s[0] - l[0]
        elif s[1] != l[1]:
            kind, delta = "TIMING", 0
        else:
            continue
        breaks.append(
            {
                "psp_ref": key[0],
                "type": key[1],
                "currency": key[2],
                "break": kind,
                "delta_minor": delta,
            }
        )

    breaks.sort(key=lambda b: (b["psp_ref"], b["type"], b["currency"]))
    return breaks
